"use client";
/**
 * Real audio tones: the ringtone for an incoming call, the ringback you hear
 * while calling, and the message tone. Ringing always plays (a call you can't
 * hear is a missed call); the message tone has its own switch in Settings.
 * Phones only let a page play sound after a tap, so the first tap anywhere
 * primes all three. Files are generated by scripts/synth-tones.py.
 */
type Tone = "ringtone" | "ringback" | "message";
const KEY = "clink_message_tone";
const els: Partial<Record<Tone, HTMLAudioElement>> = {};

function el(t: Tone): HTMLAudioElement | null {
  if (typeof window === "undefined") return null;
  if (!els[t]) {
    const a = new Audio(`/sounds/${t}.mp3`);
    a.preload = "auto";
    a.loop = t !== "message";
    a.volume = t === "ringback" ? 0.5 : t === "message" ? 0.7 : 0.9;
    els[t] = a;
  }
  return els[t]!;
}

let primed = false;
/** Call once at startup: the first user gesture unlocks audio for later. */
export function primeTones() {
  if (typeof window === "undefined" || primed) return;
  const unlock = () => {
    primed = true;
    for (const t of ["ringtone", "ringback", "message"] as const) {
      const a = el(t);
      if (!a) continue;
      a.muted = true;
      void a
        .play()
        .then(() => {
          a.pause();
          a.currentTime = 0;
          a.muted = false;
        })
        .catch(() => {
          a.muted = false;
        });
    }
    window.removeEventListener("pointerdown", unlock, true);
    window.removeEventListener("keydown", unlock, true);
  };
  window.addEventListener("pointerdown", unlock, true);
  window.addEventListener("keydown", unlock, true);
}

export function startTone(t: "ringtone" | "ringback") {
  stopTones();
  const a = el(t);
  if (!a) return;
  a.currentTime = 0;
  void a.play().catch(() => undefined);
}

export function stopTones() {
  for (const t of ["ringtone", "ringback"] as const) {
    const a = els[t];
    if (a) {
      a.pause();
      a.currentTime = 0;
    }
  }
}

export function messageToneOn(): boolean {
  try {
    return localStorage.getItem(KEY) !== "off";
  } catch {
    return true;
  }
}
export function setMessageTone(on: boolean) {
  try {
    localStorage.setItem(KEY, on ? "on" : "off");
  } catch {
    /* storage blocked */
  }
}

export function playMessageTone() {
  if (!messageToneOn()) return;
  const a = el("message");
  if (!a) return;
  a.currentTime = 0;
  void a.play().catch(() => undefined);
}
